CREATE OR REPLACE FUNCTION private.guard_report_child()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare record jsonb; parent_status text; parent_id uuid; actual_parent uuid;
begin
  record:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  parent_id:=(record->>'student_result_id')::uuid;
  select status into parent_status from public.student_results where school_id=(record->>'school_id')::uuid and id=parent_id for update;
  if parent_status is distinct from 'draft' then raise exception 'Only draft report data can be edited.'; end if;
  if tg_op='UPDATE' and (old.school_id<>new.school_id or old.student_result_id<>new.student_result_id) then raise exception 'Report child ownership cannot change.'; end if;
  if tg_table_name='result_comments' and (record->>'academic_result_id') is not null then
    select student_result_id into actual_parent from public.academic_results where id=(record->>'academic_result_id')::uuid and school_id=(record->>'school_id')::uuid;
    if actual_parent is distinct from parent_id then raise exception 'Subject comment must belong to the same report.'; end if;
  end if;
  if tg_table_name='academic_results' then
    select status into parent_status from public.result_batches where id=(record->>'batch_id')::uuid and school_id=(record->>'school_id')::uuid for update;
    if parent_status is distinct from 'draft' then raise exception 'Only draft batches accept result rows.'; end if;
  end if;
  if tg_op='DELETE' then return old; end if; return new;
end; $function$

CREATE OR REPLACE FUNCTION private.guard_report_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if tg_op='INSERT' and new.status<>'draft' then raise exception 'New reports start as drafts.'; end if;
  if tg_op='UPDATE' and old.status='published' then raise exception 'Published reports are immutable; revoke verification or issue a separate corrected report version.'; end if;
  if tg_op='UPDATE' and (to_jsonb(new)-array['status','published_at','published_snapshot','updated_at']) is distinct from (to_jsonb(old)-array['status','published_at','published_snapshot','updated_at']) then raise exception 'Report academic identity cannot change.'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION private.guard_result_batch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin
  if tg_op='INSERT' then
    if new.status<>'draft' then raise exception 'New result batches start as drafts.'; end if;
    if not exists(select 1 from public.subject_offerings where school_id=new.school_id and id=new.offering_id and assessment_scheme_id=new.assessment_scheme_id and grading_scale_id=new.grading_scale_id) then raise exception 'Batch configuration must match its subject offering.'; end if;
    if not exists(select 1 from public.assessment_schemes where school_id=new.school_id and id=new.assessment_scheme_id and status='active')
      or not exists(select 1 from public.grading_scales where school_id=new.school_id and id=new.grading_scale_id and status='active') then raise exception 'Results require active assessment and grading versions.'; end if;
  elsif old.status='published' then raise exception 'Published batches are immutable.';
  elsif (to_jsonb(new)-array['status','updated_at']) is distinct from (to_jsonb(old)-array['status','updated_at']) then raise exception 'Batch scope and configuration cannot be rewritten.';
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION private.guard_result_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous jsonb; identity_key text;
begin
  if new.supersedes_id is null then
    if new.version<>1 then raise exception 'Initial result version must be one.'; end if;
  else
    execute format('select to_jsonb(r) from public.%I r where school_id=$1 and id=$2',tg_table_name) into previous using new.school_id,new.supersedes_id;
    identity_key:=case when tg_table_name='student_results' then 'enrollment_id' else 'offering_id' end;
    if previous is null or previous->>'status'<>'published' or (previous->>'version')::integer+1<>new.version
      or previous->>'term_id'<>new.term_id::text or previous->>identity_key<>to_jsonb(new)->>identity_key then
      raise exception 'Corrections must follow a published version of the same academic result.';
    end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION private.guard_score()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare maximum numeric; batch_status text; report_status text;
record public.assessment_scores;
begin
  record:=case when tg_op='DELETE' then old else new end;
  select b.status,r.status into batch_status,report_status from public.academic_results a
    join public.result_batches b on b.school_id=a.school_id and b.id=a.batch_id join public.student_results r on r.school_id=a.school_id and r.id=a.student_result_id
    where a.school_id=record.school_id and a.id=record.academic_result_id for update of b,r;
  if batch_status is distinct from 'draft' or report_status is distinct from 'draft' then raise exception 'Only draft scores can be edited.'; end if;
  select max_score into maximum from public.assessment_components where school_id=record.school_id and id=record.component_id and scheme_id=record.assessment_scheme_id and active;
  if maximum is null or record.score>maximum then raise exception 'Score exceeds its configured component maximum.'; end if;
  if tg_op='DELETE' then return old; end if; return new;
end; $function$

CREATE OR REPLACE FUNCTION private.lock_config_child()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parent_id uuid; previous_id uuid; parent_status text;
begin
  parent_id := case when tg_op='DELETE' then (to_jsonb(old)->>tg_argv[1])::uuid else (to_jsonb(new)->>tg_argv[1])::uuid end;
  previous_id := case when tg_op='UPDATE' then (to_jsonb(old)->>tg_argv[1])::uuid else parent_id end;
  execute format('select status from public.%I where id=$1 for update',tg_argv[0]) into parent_status using previous_id;
  if parent_status is distinct from 'draft' then raise exception 'Create a new configuration version; active versions are immutable.'; end if;
  execute format('select status from public.%I where id=$1 for update',tg_argv[0]) into parent_status using parent_id;
  if parent_status is distinct from 'draft' then raise exception 'Only draft configuration is editable.'; end if;
  if tg_op='DELETE' then return old; end if; return new;
end; $function$

CREATE OR REPLACE FUNCTION private.lock_simple_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if tg_op='INSERT' and new.status<>'draft' then raise exception 'Configuration starts as a draft.'; end if;
  if tg_op='UPDATE' and old.status<>'draft' and ((to_jsonb(new)-'status') is distinct from (to_jsonb(old)-'status') or (new.status is distinct from old.status and not(old.status='active' and new.status='archived'))) then raise exception 'Create a new configuration version.'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION private.sync_assignment_teacher()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare teacher public.teachers;
begin
  if new.teacher_id is null then
    if new.user_id is null then raise exception 'A teacher entity or linked account is required.'; end if;
    insert into public.teachers(school_id,user_id,display_name,email)
      select new.school_id,u.id,coalesce(p.display_name,'Teacher'),u.email from auth.users u left join public.profiles p on p.id=u.id where u.id=new.user_id
      on conflict(school_id,user_id) do nothing;
    select * into teacher from public.teachers where school_id=new.school_id and user_id=new.user_id;
    new.teacher_id:=teacher.id;
  else select * into teacher from public.teachers where school_id=new.school_id and id=new.teacher_id;
  end if;
  if teacher.id is null or teacher.user_id is distinct from new.user_id then raise exception 'Teacher and Auth account must match in this school.'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION private.validate_config_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare total numeric; first_score numeric; last_score numeric; invalid boolean;
begin
  if tg_op='INSERT' and new.status<>'draft' then raise exception 'New configuration must start as a draft.'; end if;
  if tg_op='UPDATE' and old.status<>'draft' then
    if to_jsonb(new)-'status' is distinct from to_jsonb(old)-'status' or (new.status is distinct from old.status and not(old.status='active' and new.status='archived')) then
      raise exception 'Active/archived configuration versions are immutable.';
    end if;
  end if;
  if new.status='active' and (tg_op='INSERT' or old.status='draft') then
    if tg_table_name='assessment_schemes' then
      select sum(weight) into total from public.assessment_components where school_id=new.school_id and scheme_id=new.id and active;
      if total is distinct from 100::numeric then raise exception 'Active assessment weights must add up to 100.'; end if;
    else
      select min(minimum_score),max(maximum_score) into first_score,last_score from public.grading_scale_items where school_id=new.school_id and scale_id=new.id;
      select exists(select 1 from (select minimum_score,lag(maximum_score) over(order by minimum_score) previous_end from public.grading_scale_items where school_id=new.school_id and scale_id=new.id) b where previous_end is not null and minimum_score<>previous_end) into invalid;
      if first_score is distinct from 0::numeric or last_score is distinct from 100::numeric or invalid then raise exception 'Grading bands must cover 0 through 100 without gaps or overlaps.'; end if;
    end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.assign_school_teacher(requested_school uuid, teacher_email text, teacher_role text, requested_class uuid, requested_subject uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare teacher_id uuid; assignment_id uuid;
begin
  if not private.can_manage_school(requested_school) then raise exception 'School administrator access required.'; end if;
  if teacher_role not in ('subject_teacher', 'class_teacher') then raise exception 'Only teacher roles can be assigned here.'; end if;
  select id into teacher_id from auth.users where lower(email) = lower(btrim(teacher_email)) and email_confirmed_at is not null;
  if teacher_id is null then raise exception 'Ask the teacher to sign up and confirm their email first.'; end if;
  insert into public.school_memberships(school_id, user_id, role) values (requested_school, teacher_id, teacher_role)
    on conflict(school_id, user_id, role) do update set status = 'active';
  insert into public.teacher_assignments(school_id, user_id, role, class_id, subject_id)
    values(requested_school, teacher_id, teacher_role, requested_class, requested_subject)
    on conflict do nothing returning id into assignment_id;
  if assignment_id is null then
    select id into assignment_id from public.teacher_assignments where school_id = requested_school and user_id = teacher_id
      and role = teacher_role and class_id = requested_class and subject_id is not distinct from requested_subject;
  end if;
  return assignment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_teacher_entity(requested_school uuid, requested_teacher uuid, teacher_role text, requested_class uuid, requested_subject uuid DEFAULT NULL::uuid, requested_session uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare teacher public.teachers; assigned uuid;
begin
  if not private.can_manage_school(requested_school) then raise exception 'School administrator access required.'; end if;
  if teacher_role is null or teacher_role not in ('class_teacher','subject_teacher') then raise exception 'Only teaching roles are allowed.'; end if;
  select * into teacher from public.teachers where school_id=requested_school and id=requested_teacher and status='active';
  if not found then raise exception 'Active teacher not found in this school.'; end if;
  if teacher.user_id is not null then
    insert into public.school_memberships(school_id,user_id,role) values(requested_school,teacher.user_id,teacher_role)
      on conflict(school_id,user_id,role) do update set status='active';
  end if;
  insert into public.teacher_assignments(school_id,teacher_id,user_id,role,class_id,subject_id,session_id)
    values(requested_school,teacher.id,teacher.user_id,teacher_role,requested_class,requested_subject,requested_session) returning id into assigned;
  return assigned;
end; $function$

CREATE OR REPLACE FUNCTION public.calculate_academic_result(requested_result uuid)
 RETURNS TABLE(total numeric, grade text, remark text, complete boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.academic_results; scale uuid; weighted numeric; missing boolean;
begin
  select * into result from public.academic_results where id=requested_result;
  if not found or not private.can_access_academic_result(result.school_id,result.id,false) then raise exception 'Assigned result access required.'; end if;
  select grading_scale_id into scale from public.result_batches where id=result.batch_id;
  select round(sum(coalesce(s.score,0)/c.max_score*c.weight),3),bool_or(s.id is null) into weighted,missing
    from public.assessment_components c left join public.assessment_scores s on s.school_id=c.school_id and s.component_id=c.id and s.academic_result_id=result.id
    where c.school_id=result.school_id and c.scheme_id=result.assessment_scheme_id and c.active;
  return query select weighted,case when missing then null else g.grade end,case when missing then null else g.remark end,not missing
    from (select 1) seed left join public.grading_scale_items g on g.school_id=result.school_id and g.scale_id=scale
      and weighted>=g.minimum_score and (weighted<g.maximum_score or (weighted=100 and g.maximum_score=100));
end; $function$

CREATE OR REPLACE FUNCTION public.create_school_catalog_item(requested_school uuid, item_kind text, item_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item_id uuid;
begin
  if not private.can_manage_school(requested_school) then raise exception 'School administrator access required.'; end if;
  if item_kind = 'class' then
    insert into public.school_classes(school_id, name) values(requested_school, btrim(item_name)) returning id into item_id;
  elsif item_kind = 'subject' then
    insert into public.school_subjects(school_id, name) values(requested_school, btrim(item_name)) returning id into item_id;
  else raise exception 'Choose class or subject.';
  end if;
  return item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_published_report(requested_result uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.student_results;
begin
  select * into result from public.student_results where id=requested_result and status='published';
  if not found or not private.can_read_full_report(result.school_id,result.id) then raise exception 'Full report access required.'; end if;
  return result.published_snapshot;
end; $function$

CREATE OR REPLACE FUNCTION public.get_school_entitlements(requested_school uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare entitlements jsonb; overrides jsonb; chosen_plan uuid;
begin
  if not(private.is_platform_admin() or private.has_school_role(requested_school,array['school_admin','subject_teacher','class_teacher','student','parent'])) then raise exception 'Active school access required.'; end if;
  select plan_id into chosen_plan from public.school_subscriptions where school_id=requested_school and status in ('active','trialing') and starts_at<=now() and ends_at>now() order by starts_at desc,id limit 1;
  select coalesce(jsonb_object_agg(feature_code,value),'{}') into entitlements from public.plan_features where plan_id=chosen_plan;
  select coalesce(jsonb_object_agg(feature_code,value),'{}') into overrides from public.school_feature_overrides where school_id=requested_school and (expires_at is null or expires_at>now());
  return entitlements||overrides;
end; $function$

CREATE OR REPLACE FUNCTION public.link_teacher_account(requested_school uuid, requested_teacher uuid, teacher_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare linked_user uuid; teacher public.teachers;
begin
  if not private.can_manage_school(requested_school) then raise exception 'School administrator access required.'; end if;
  select * into teacher from public.teachers where school_id=requested_school and id=requested_teacher for update;
  if not found or teacher.user_id is not null then raise exception 'Choose an unlinked teacher in this school.'; end if;
  select id into linked_user from auth.users where lower(email)=lower(btrim(teacher_email)) and email_confirmed_at is not null;
  if linked_user is null then raise exception 'The account must exist and have a confirmed email.'; end if;
  update public.teachers set user_id=linked_user where id=teacher.id;
  insert into public.school_memberships(school_id,user_id,role)
    select distinct requested_school,linked_user,role from public.teacher_assignments where school_id=requested_school and teacher_id=teacher.id
    on conflict(school_id,user_id,role) do update set status='active';
  update public.teacher_assignments set user_id=linked_user where school_id=requested_school and teacher_id=teacher.id;
end; $function$

CREATE OR REPLACE FUNCTION public.platform_create_school(school_name text, school_slug text, administrator_email text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare administrator uuid; created_school uuid;
begin
  if not private.is_platform_admin() then raise exception 'Platform administrator access required.'; end if;
  select id into administrator from auth.users where lower(email) = lower(btrim(administrator_email)) and email_confirmed_at is not null;
  if administrator is null then raise exception 'The school administrator must sign up and confirm their email first.'; end if;
  insert into public.schools(name, slug) values(btrim(school_name), lower(btrim(school_slug))) returning id into created_school;
  insert into public.school_memberships(school_id, user_id, role) values(created_school, administrator, 'school_admin');
  return created_school;
end;
$function$

CREATE OR REPLACE FUNCTION public.platform_remove_school(requested_school uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin
  if not private.is_platform_admin() then raise exception 'Platform administrator access required.'; end if;
  update public.schools set status='suspended',archived_at=coalesce(archived_at,now()) where id=requested_school;
  if not found then raise exception 'School not found.'; end if;
end; $function$

CREATE OR REPLACE FUNCTION public.platform_set_school_status(requested_school uuid, requested_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin
  if not private.is_platform_admin() then raise exception 'Platform administrator access required.'; end if;
  if requested_status is null or requested_status not in ('active','suspended') then raise exception 'Invalid school status.'; end if;
  update public.schools set status=requested_status where id=requested_school and archived_at is null;
  if not found then raise exception 'School not found or archived.'; end if;
end; $function$

CREATE OR REPLACE FUNCTION public.register_my_school(school_name text, school_slug text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid := auth.uid(); registered_school uuid;
begin
  if caller is null or not exists (select 1 from auth.users where id = caller and email_confirmed_at is not null) then
    raise exception 'Confirm your email before registering a school.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(caller::text, 0));
  select school_id into registered_school from private.school_registrations where user_id = caller;
  if found then
    if registered_school is null then raise exception 'Your school registration was removed. Contact the platform owner.'; end if;
    return registered_school;
  end if;
  if exists(select 1 from public.school_memberships where user_id = caller) then
    raise exception 'This account already has a school membership. Use a separate administrator account to register a new school.';
  end if;
  insert into public.schools(name, slug) values (btrim(school_name), lower(btrim(school_slug))) returning id into registered_school;
  insert into public.school_memberships(school_id, user_id, role) values (registered_school, caller, 'school_admin');
  insert into private.school_registrations(user_id, school_id) values (caller, registered_school);
  return registered_school;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_teacher_assignment(requested_assignment uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare assignment public.teacher_assignments;
begin
  select * into assignment from public.teacher_assignments where id = requested_assignment for update;
  if not found or not private.can_manage_school(assignment.school_id) then raise exception 'School administrator access required.'; end if;
  delete from public.teacher_assignments where id = requested_assignment;
  if not exists(select 1 from public.teacher_assignments where school_id = assignment.school_id and user_id = assignment.user_id and role = assignment.role) then
    delete from public.school_memberships where school_id = assignment.school_id and user_id = assignment.user_id and role = assignment.role;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_result_verification(requested_result uuid, reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.student_results;
begin
  select * into result from public.student_results where id=requested_result and status='published';
  if not found or not private.can_manage_school(result.school_id) then raise exception 'School administrator access required.'; end if;
  update public.result_verifications set status='revoked',revoked_at=now(),revocation_reason=reason where student_result_id=result.id;
end; $function$

CREATE OR REPLACE FUNCTION public.transition_result_batch(requested_batch uuid, next_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare batch public.result_batches;
begin
  select * into batch from public.result_batches where id=requested_batch for update;
  if not found then raise exception 'Result batch not found.'; end if;
  if batch.status='draft' and next_status='submitted' then
    if not private.can_access_offering(batch.school_id,batch.offering_id,true) then raise exception 'Assigned subject teacher access required.'; end if;
    if not exists(select 1 from public.academic_results where batch_id=batch.id) or exists(select 1 from public.academic_results a cross join public.assessment_components c
      where a.batch_id=batch.id and c.scheme_id=batch.assessment_scheme_id and c.active and not exists(select 1 from public.assessment_scores s where s.academic_result_id=a.id and s.component_id=c.id)) then raise exception 'Every result needs all active assessment component scores.'; end if;
  elsif not private.can_manage_school(batch.school_id) or not ((batch.status='submitted' and next_status='under_review') or (batch.status='under_review' and next_status='approved') or (batch.status='approved' and next_status='published')) then raise exception 'Invalid or unauthorized result transition.';
  end if;
  update public.result_batches set status=next_status,updated_at=now() where id=batch.id;
end; $function$

CREATE OR REPLACE FUNCTION public.transition_student_result(requested_result uuid, next_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.student_results; snapshot jsonb;
begin
  select * into result from public.student_results where id=requested_result for update;
  if not found then raise exception 'Student result not found.'; end if;
  if result.status='draft' and next_status='submitted' then
    if not private.can_edit_report(result.school_id,result.id) then raise exception 'Assigned class teacher or school administrator access required.'; end if;
  elsif not private.can_manage_school(result.school_id) or not ((result.status='submitted' and next_status='under_review') or (result.status='under_review' and next_status='approved') or (result.status='approved' and next_status='published')) then raise exception 'Invalid or unauthorized report transition.';
  end if;
  if next_status='published' then
    if result.template_id is null or not exists(select 1 from public.result_templates where id=result.template_id and school_id=result.school_id and status='active') then raise exception 'An active report template is required.'; end if;
    if not exists(select 1 from public.academic_results where student_result_id=result.id) or exists(select 1 from public.academic_results a join public.result_batches b on b.id=a.batch_id where a.student_result_id=result.id and b.status<>'published') then raise exception 'Publish all included subject batches before publishing this report.'; end if;
    select jsonb_build_object(
      'schema_version',1,'school',to_jsonb(s),'student',to_jsonb(student),'enrollment',to_jsonb(e),'session',to_jsonb(session),'term',to_jsonb(term),
      'class',to_jsonb(class),'template',to_jsonb(template),
      'academics',(select coalesce(jsonb_agg(jsonb_build_object('subject',to_jsonb(subject),'assessment_scheme',to_jsonb(scheme),'grading_scale',to_jsonb(scale),
        'grading_bands',(select jsonb_agg(to_jsonb(g) order by minimum_score) from public.grading_scale_items g where g.scale_id=scale.id),
        'calculation',to_jsonb(calculation),'components',(select jsonb_agg(jsonb_build_object('name',c.name,'max_score',c.max_score,'weight',c.weight,'score',score.score) order by c.sort_order)
          from public.assessment_components c join public.assessment_scores score on score.component_id=c.id and score.academic_result_id=a.id where c.scheme_id=a.assessment_scheme_id and c.active))), '[]')
        from public.academic_results a join public.result_batches b on b.id=a.batch_id join public.subject_offerings o on o.id=b.offering_id
        join public.school_subjects subject on subject.id=o.subject_id join public.assessment_schemes scheme on scheme.id=b.assessment_scheme_id
        join public.grading_scales scale on scale.id=b.grading_scale_id cross join lateral public.calculate_academic_result(a.id) calculation where a.student_result_id=result.id),
      'ratings',(select coalesce(jsonb_agg(jsonb_build_object('domain',cat.domain,'category',cat.name,'item',item.name,'value',rating.value,'label',key.label)),'[]')
        from public.student_ratings rating join public.rating_items item on item.id=rating.item_id join public.rating_categories cat on cat.id=item.category_id
        join public.rating_scale_items key on key.scale_id=rating.scale_id and key.value=rating.value where rating.student_result_id=result.id),
      'attendance',(select to_jsonb(attendance) from public.result_attendance attendance where attendance.student_result_id=result.id),
      'comments',(select coalesce(jsonb_agg(jsonb_build_object('type',comment_type,'body',body,'academic_result_id',academic_result_id)),'[]') from public.result_comments where student_result_id=result.id))
    into snapshot from public.schools s join public.student_enrollments e on e.school_id=s.id and e.id=result.enrollment_id
      join public.students student on student.id=e.student_id join public.school_classes class on class.id=e.class_id
      join public.academic_sessions session on session.id=e.session_id join public.academic_terms term on term.id=result.term_id
      join public.result_templates template on template.id=result.template_id where s.id=result.school_id;
    update public.student_results set status='published',published_at=now(),published_snapshot=snapshot,updated_at=now() where id=result.id;
    insert into public.result_verifications(school_id,student_result_id) values(result.school_id,result.id);
  else update public.student_results set status=next_status,updated_at=now() where id=result.id;
  end if;
end; $function$
